// Spike S2: LibreOffice runner, shaped like LLD Part 2 §14.2 / §14.3.
// Arguments are always an array and a shell is never used (HLD §14). Every path passed in is
// generated by the spike scripts, never taken from document content.
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { basename, extname, join } from 'node:path';
import { pathToFileURL } from 'node:url';

export const FILTER = {
  fodt: 'OpenDocument Text Flat XML',
  fods: 'OpenDocument Spreadsheet Flat XML',
  docx: 'MS Word 2007 XML',
  odt: 'writer8',
  xlsx: 'Calc MS Excel 2007 XML',
  ods: 'calc8',
};

export function locateSoffice() {
  if (process.env.SOFFICE) return process.env.SOFFICE;
  const c =
    process.platform === 'win32'
      ? [join(process.env.ProgramFiles ?? 'C:\\Program Files', 'LibreOffice', 'program', 'soffice.exe')]
      : ['/usr/bin/soffice', '/usr/lib/libreoffice/program/soffice', '/opt/libreoffice/program/soffice'];
  const hit = c.find((p) => existsSync(p));
  if (!hit) throw new Error('soffice not found; set SOFFICE');
  return hit;
}

const XCU_ITEMS = [
  ['/org.openoffice.Office.Common/Security/Scripting', 'DisableMacrosExecution', 'true'],
  ['/org.openoffice.Office.Common/Security/Scripting', 'MacroSecurityLevel', '3'],
  ['/org.openoffice.Office.Common/Security/Scripting', 'BlockUntrustedRefererLinks', 'true'],
  ['/org.openoffice.Office.Calc/Formula/Load', 'OOXMLRecalcMode', '1'],
  ['/org.openoffice.Office.Calc/Formula/Load', 'ODFRecalcMode', '1'],
];

/** Creates (or re-creates) a profile slot seeded as in LLD §14.3. `seed=false` gives an empty profile. */
export function resetProfile(profileDir, { seed = true } = {}) {
  rmSync(profileDir, { recursive: true, force: true });
  mkdirSync(join(profileDir, 'user'), { recursive: true });
  if (!seed) return;
  const items = XCU_ITEMS.map(
    ([p, n, v]) => `<item oor:path="${p}"><prop oor:name="${n}" oor:op="fuse"><value>${v}</value></prop></item>`,
  ).join('\n');
  writeFileSync(
    join(profileDir, 'user', 'registrymodifications.xcu'),
    `<?xml version="1.0" encoding="UTF-8"?>\n<oor:items xmlns:oor="http://openoffice.org/2001/registry" xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">\n${items}\n</oor:items>\n`,
  );
}

function killTree(child) {
  if (process.platform === 'win32') {
    spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { shell: false, windowsHide: true });
  } else {
    try {
      process.kill(-child.pid, 'SIGKILL');
    } catch {
      /* already gone */
    }
  }
}

/**
 * Converts `inPath` to `target` (a FILTER key, or `ext:Filter` for image targets such as `png`).
 * Resolves `{ ok, outPath, ms, code, stderr, timedOut }`. Success is judged by the output file.
 */
export function convert({ soffice = locateSoffice(), inPath, outDir, target, profileDir, timeoutMs = 120_000, extraArgs = [] }) {
  const [ext, filter] = target.includes(':') ? target.split(/:(.*)/s) : [target, FILTER[target]];
  const convertTo = filter ? `${ext}:${filter}` : ext;
  mkdirSync(outDir, { recursive: true });
  const args = [
    `-env:UserInstallation=${pathToFileURL(profileDir).href}`,
    '--headless', '--invisible', '--norestore', '--nologo', '--nodefault', '--nolockcheck',
    ...extraArgs,
    '--convert-to', convertTo, '--outdir', outDir, inPath,
  ];
  const env = { ...process.env };
  if (process.platform !== 'win32') env.HOME = profileDir;
  const t0 = performance.now();
  return new Promise((resolve) => {
    const child = spawn(soffice, args, {
      shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
      detached: process.platform !== 'win32', env,
    });
    let stderr = '';
    let stdout = '';
    child.stdout.on('data', (d) => { stdout = (stdout + d).slice(-4096); });
    child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-4096); });
    let timedOut = false;
    const timer = setTimeout(() => { timedOut = true; killTree(child); }, timeoutMs);
    child.on('error', (e) => { clearTimeout(timer); resolve({ ok: false, error: String(e), ms: performance.now() - t0 }); });
    child.on('exit', (code) => {
      clearTimeout(timer);
      const ms = performance.now() - t0;
      const outPath = join(outDir, basename(inPath, extname(inPath)) + '.' + ext);
      const ok = !timedOut && existsSync(outPath) && statSync(outPath).size > 0;
      resolve({ ok, outPath, ms, code, timedOut, stderr: stderr.trim(), stdout: stdout.trim() });
    });
  });
}
